let next_tag = ref 0

let htable = WH.create 5003

let hashcons d =
  let d = H.tag !next_tag d in
  let o = WH.merge htable d in
  if o == d then incr next_tag;
  o

let unique d =
  let d = H.tag !next_tag d in
  incr next_tag;
  d
